SET LOCAL search_path = pg_catalog;
WITH rels AS (
 SELECT c.* FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND c.relkind IN ('r','p') AND (c.relname LIKE 'website%' OR c.relname IN ('agents','cron_heartbeat','dream_issues','manager_tasks','media_insights','memories','outputs','platform_config','platform_tokens','projects','revenue_snapshots','run_logs','runs','workflows'))
), objects AS (
 SELECT 'table' AS kind,c.relname::text AS key,jsonb_build_object('owner',pg_catalog.pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl::text) AS definition FROM rels c
 UNION ALL SELECT 'column',c.relname||'.'||a.attname,jsonb_build_object('type',pg_catalog.format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default_md5',md5(pg_catalog.pg_get_expr(d.adbin,d.adrelid)),'identity',a.attidentity,'generated',a.attgenerated) FROM rels c JOIN pg_catalog.pg_attribute a ON a.attrelid=c.oid LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE a.attnum>0 AND NOT a.attisdropped
 UNION ALL SELECT 'constraint',c.relname||'.'||p.conname,jsonb_build_object('type',p.contype,'validated',p.convalidated,'deferrable',p.condeferrable,'deferred',p.condeferred,'definition_md5',md5(pg_catalog.pg_get_constraintdef(p.oid,true))) FROM rels c JOIN pg_catalog.pg_constraint p ON p.conrelid=c.oid
 UNION ALL SELECT 'index',c.relname||'.'||x.relname,jsonb_build_object('unique',i.indisunique,'primary',i.indisprimary,'valid',i.indisvalid,'definition_md5',md5(pg_catalog.pg_get_indexdef(i.indexrelid))) FROM rels c JOIN pg_catalog.pg_index i ON i.indrelid=c.oid JOIN pg_catalog.pg_class x ON x.oid=i.indexrelid
 UNION ALL SELECT 'policy',c.relname||'.'||p.polname,jsonb_build_object('command',p.polcmd,'permissive',p.polpermissive,'roles',(SELECT jsonb_agg(CASE WHEN r=0 THEN 'public' ELSE pg_catalog.pg_get_userbyid(r) END ORDER BY r) FROM unnest(p.polroles) r),'using_md5',md5(pg_catalog.pg_get_expr(p.polqual,p.polrelid)),'check_md5',md5(pg_catalog.pg_get_expr(p.polwithcheck,p.polrelid))) FROM rels c JOIN pg_catalog.pg_policy p ON p.polrelid=c.oid
 UNION ALL SELECT 'trigger',c.relname||'.'||t.tgname,jsonb_build_object('enabled',t.tgenabled,'definition_md5',md5(pg_catalog.pg_get_triggerdef(t.oid,true))) FROM rels c JOIN pg_catalog.pg_trigger t ON t.tgrelid=c.oid WHERE NOT t.tgisinternal
 UNION ALL SELECT 'function',p.proname||'('||pg_catalog.pg_get_function_identity_arguments(p.oid)||')',jsonb_build_object('owner',pg_catalog.pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl::text,'definition_md5',md5(pg_catalog.pg_get_functiondef(p.oid))) FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f' AND (p.proname LIKE 'website%' OR p.oid IN (SELECT t.tgfoid FROM rels c JOIN pg_catalog.pg_trigger t ON t.tgrelid=c.oid WHERE NOT t.tgisinternal))

 UNION ALL SELECT 'table_api',c.relname||'.'||r.role,jsonb_build_object('select',pg_catalog.has_table_privilege(r.role,c.oid,'SELECT'),'insert',pg_catalog.has_table_privilege(r.role,c.oid,'INSERT'),'update',pg_catalog.has_table_privilege(r.role,c.oid,'UPDATE'),'delete',pg_catalog.has_table_privilege(r.role,c.oid,'DELETE'),'truncate',pg_catalog.has_table_privilege(r.role,c.oid,'TRUNCATE'),'references',pg_catalog.has_table_privilege(r.role,c.oid,'REFERENCES'),'trigger',pg_catalog.has_table_privilege(r.role,c.oid,'TRIGGER')) FROM rels c CROSS JOIN (VALUES ('anon'),('authenticated'),('service_role')) r(role)
 UNION ALL SELECT 'column_acl',c.relname||'.'||a.attname,jsonb_build_object('acl',a.attacl::text) FROM rels c JOIN pg_catalog.pg_attribute a ON a.attrelid=c.oid WHERE a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL
 UNION ALL SELECT 'function_api',p.proname||'('||pg_catalog.pg_get_function_identity_arguments(p.oid)||').'||r.role,jsonb_build_object('execute',pg_catalog.has_function_privilege(r.role,p.oid,'EXECUTE')) FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace CROSS JOIN (VALUES ('anon'),('authenticated'),('service_role')) r(role) WHERE n.nspname='public' AND p.prokind='f' AND (p.proname LIKE 'website%' OR p.oid IN (SELECT t.tgfoid FROM rels c JOIN pg_catalog.pg_trigger t ON t.tgrelid=c.oid WHERE NOT t.tgisinternal))
 UNION ALL SELECT 'schema_api',n.nspname||'.'||r.role,jsonb_build_object('usage',pg_catalog.has_schema_privilege(r.role,n.oid,'USAGE'),'create',pg_catalog.has_schema_privilege(r.role,n.oid,'CREATE')) FROM pg_catalog.pg_namespace n CROSS JOIN (VALUES ('anon'),('authenticated'),('service_role')) r(role) WHERE n.nspname IN ('public','auth','storage')
 UNION ALL SELECT 'default_acl',pg_catalog.pg_get_userbyid(d.defaclrole)||'.'||coalesce(n.nspname,'*')||'.'||d.defaclobjtype::text,jsonb_build_object('acl',d.defaclacl::text) FROM pg_catalog.pg_default_acl d LEFT JOIN pg_catalog.pg_namespace n ON n.oid=d.defaclnamespace WHERE d.defaclrole IN (SELECT oid FROM pg_catalog.pg_roles WHERE rolname IN ('postgres','supabase_admin')) AND (d.defaclnamespace=0 OR n.nspname IN ('public','auth','storage'))
 UNION ALL SELECT 'role_membership',pg_catalog.pg_get_userbyid(m.member)||'.'||pg_catalog.pg_get_userbyid(m.roleid),jsonb_build_object('admin',m.admin_option,'inherit',m.inherit_option,'set',m.set_option) FROM pg_catalog.pg_auth_members m WHERE m.member IN (SELECT oid FROM pg_catalog.pg_roles WHERE rolname IN ('postgres','supabase_admin','anon','authenticated','service_role'))
 UNION ALL SELECT 'role',r.rolname,jsonb_build_object('superuser',r.rolsuper,'bypass_rls',r.rolbypassrls,'inherit',r.rolinherit,'login',r.rolcanlogin) FROM pg_catalog.pg_roles r WHERE r.rolname IN ('postgres','supabase_admin','anon','authenticated','service_role')
)
SELECT json_build_object('search_path',current_setting('search_path'),'objects',(SELECT json_agg(o ORDER BY kind,key) FROM objects o)) AS catalog;